type schemaProperty struct {
	WireName string      `json:"wire_name"`
	Required bool        `json:"required"`
	Shape    *schemaNode `json:"shape"`
}

type schemaNode struct {
	Kind                  string           `json:"kind"`
	Value                 any              `json:"value"`
	Values                []any            `json:"values"`
	OpenStrings           bool             `json:"open_strings"`
	Items                 *schemaNode      `json:"items"`
	Properties            []schemaProperty `json:"properties"`
	ForbiddenPropertySets [][]string       `json:"forbidden_property_sets"`
	Mode                  string           `json:"mode"`
	Variants              []*schemaNode    `json:"variants"`
	Discriminator         *string          `json:"discriminator"`
	Name                  string           `json:"name"`
}

func loadSchemaDescriptors(source string) map[string]*schemaNode {
	decoder := json.NewDecoder(strings.NewReader(source))
	decoder.UseNumber()
	var descriptors map[string]*schemaNode
	if err := decoder.Decode(&descriptors); err != nil {
		panic(fmt.Sprintf("invalid generated schema descriptors: %v", err))
	}
	return descriptors
}

func loadSchemaNode(source string) *schemaNode {
	decoder := json.NewDecoder(strings.NewReader(source))
	decoder.UseNumber()
	var node schemaNode
	if err := decoder.Decode(&node); err != nil {
		panic(fmt.Sprintf("invalid generated schema node: %v", err))
	}
	return &node
}

func parseRoot[T any](name string, input []byte) ParseResult[T] {
	raw := append(json.RawMessage(nil), input...)
	value, err := decodeJSON(input)
	if err != nil {
		return ParseResult[T]{
			Diagnostics: []ParseDiagnostic{{
				Code: DiagnosticInvalidJSON, Severity: SeverityError, Message: err.Error(),
			}},
		}
	}

	diagnostics := make([]ParseDiagnostic, 0)
	checkNode(schemaDescriptors[name], value, "", &diagnostics)
	result := ParseResult[T]{Raw: raw, Diagnostics: diagnostics}
	if hasErrors(diagnostics) {
		return result
	}
	if err := json.Unmarshal(input, &result.Value); err != nil {
		result.Diagnostics = append(result.Diagnostics, ParseDiagnostic{
			Code: DiagnosticInvalidType, Severity: SeverityError, Message: err.Error(),
		})
		return result
	}
	result.OK = true
	return result
}

func decodeJSON(input []byte) (any, error) {
	decoder := json.NewDecoder(bytes.NewReader(input))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return nil, err
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		if err == nil {
			return nil, fmt.Errorf("multiple JSON values")
		}
		return nil, err
	}
	return value, nil
}

func checkNode(schema *schemaNode, value any, path string, diagnostics *[]ParseDiagnostic) {
	if schema == nil {
		addError(diagnostics, path, DiagnosticInvalidType, "Missing generated schema")
		return
	}
	switch schema.Kind {
	case "any":
		return
	case "never":
		addError(diagnostics, path, DiagnosticInvalidType, "Value is forbidden")
	case "null":
		if value != nil {
			addError(diagnostics, path, DiagnosticInvalidType, "Expected null")
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			addError(diagnostics, path, DiagnosticInvalidType, "Expected boolean")
		}
	case "integer":
		if number, ok := value.(json.Number); !ok || !isSafeInteger(number) {
			addError(diagnostics, path, DiagnosticInvalidType, "Expected safely representable integer")
		}
	case "number":
		if number, ok := value.(json.Number); !ok || !isFiniteNumber(number) {
			addError(diagnostics, path, DiagnosticInvalidType, "Expected finite number")
		}
	case "string":
		if _, ok := value.(string); !ok {
			addError(diagnostics, path, DiagnosticInvalidType, "Expected string")
		}
	case "literal":
		if !sameJSON(value, schema.Value) {
			addError(diagnostics, path, DiagnosticLiteralMismatch, fmt.Sprintf("Expected %s", jsonText(schema.Value)))
		}
	case "enum":
		checkEnum(schema, value, path, diagnostics)
	case "array":
		items, ok := value.([]any)
		if !ok {
			addError(diagnostics, path, DiagnosticInvalidType, "Expected array")
			return
		}
		for index, item := range items {
			checkNode(schema.Items, item, fmt.Sprintf("%s/%d", path, index), diagnostics)
		}
	case "object":
		checkObject(schema, value, path, diagnostics)
	case "intersection":
		for _, variant := range schema.Variants {
			checkNode(variant, value, path, diagnostics)
		}
	case "ref":
		checkNode(schemaDescriptors[schema.Name], value, path, diagnostics)
	case "union":
		checkUnion(schema, value, path, diagnostics)
	default:
		addError(diagnostics, path, DiagnosticInvalidType, "Unknown generated schema node")
	}
}

func checkEnum(schema *schemaNode, value any, path string, diagnostics *[]ParseDiagnostic) {
	for _, candidate := range schema.Values {
		if sameJSON(candidate, value) {
			return
		}
	}
	if _, ok := value.(string); schema.OpenStrings && ok {
		*diagnostics = append(*diagnostics, ParseDiagnostic{
			Path: path, Code: DiagnosticUnknownEnum, Severity: SeverityWarning,
			Message: fmt.Sprintf("Unknown enum value %s was preserved", jsonText(value)),
		})
		return
	}
	addError(diagnostics, path, DiagnosticInvalidType, "Value does not match the enum's scalar type")
}

func checkObject(schema *schemaNode, value any, path string, diagnostics *[]ParseDiagnostic) {
	object, ok := value.(map[string]any)
	if !ok {
		addError(diagnostics, path, DiagnosticInvalidType, "Expected object")
		return
	}
	for _, forbiddenSet := range schema.ForbiddenPropertySets {
		allPresent := true
		for _, key := range forbiddenSet {
			if _, present := object[key]; !present {
				allPresent = false
				break
			}
		}
		if allPresent {
			addError(diagnostics, path, DiagnosticInvalidType, "Forbidden property combination: "+strings.Join(forbiddenSet, ", "))
		}
	}
	for _, property := range schema.Properties {
		child, present := object[property.WireName]
		childPath := joinPath(path, property.WireName)
		if !present {
			if property.Required {
				addError(diagnostics, childPath, DiagnosticMissingRequired, "Required property is absent")
			}
			continue
		}
		checkNode(property.Shape, child, childPath, diagnostics)
	}
}

func checkUnion(schema *schemaNode, value any, path string, diagnostics *[]ParseDiagnostic) {
	if schema.Discriminator != nil {
		object, objectOK := value.(map[string]any)
		actual, discriminatorOK := object[*schema.Discriminator].(string)
		if !objectOK || !discriminatorOK {
			addError(diagnostics, joinPath(path, *schema.Discriminator), DiagnosticInvalidType, "Expected string discriminator")
			return
		}
		var branch *schemaNode
		for _, candidate := range schema.Variants {
			if discriminatorValue(candidate, *schema.Discriminator) == actual {
				branch = candidate
				break
			}
		}
		if branch == nil {
			*diagnostics = append(*diagnostics, ParseDiagnostic{
				Path: path, Code: DiagnosticUnknownVariant, Severity: SeverityWarning,
				Message: fmt.Sprintf("Unknown %s variant %s was preserved", *schema.Discriminator, jsonText(actual)),
			})
			return
		}
		branchDiagnostics := make([]ParseDiagnostic, 0)
		checkNode(branch, value, path, &branchDiagnostics)
		*diagnostics = append(*diagnostics, branchDiagnostics...)
		if hasErrors(branchDiagnostics) {
			*diagnostics = append(*diagnostics, ParseDiagnostic{
				Path: path, Code: DiagnosticInvalidKnownVariant, Severity: SeverityError,
				Message: fmt.Sprintf("Known %s variant is malformed", *schema.Discriminator),
			})
		}
		return
	}

	matches := make([][]ParseDiagnostic, 0, len(schema.Variants))
	for _, variant := range schema.Variants {
		attempt := make([]ParseDiagnostic, 0)
		checkNode(variant, value, path, &attempt)
		if !hasErrors(attempt) {
			matches = append(matches, attempt)
		}
	}
	if len(matches) == 0 {
		addError(diagnostics, path, DiagnosticNoUnionMatch, "Value matches no union branch")
	} else if schema.Mode == "oneOf" && len(matches) > 1 {
		addError(diagnostics, path, DiagnosticAmbiguousUnion, "Value matches more than one union branch")
	} else {
		*diagnostics = append(*diagnostics, matches[0]...)
	}
}

func discriminatorValue(schema *schemaNode, property string) string {
	if schema == nil {
		return ""
	}
	switch schema.Kind {
	case "ref":
		return discriminatorValue(schemaDescriptors[schema.Name], property)
	case "intersection":
		for _, variant := range schema.Variants {
			if value := discriminatorValue(variant, property); value != "" {
				return value
			}
		}
	case "object":
		for _, field := range schema.Properties {
			if field.WireName == property && field.Shape.Kind == "literal" {
				if value, ok := field.Shape.Value.(string); ok {
					return value
				}
			}
		}
	}
	return ""
}

func hasErrors(diagnostics []ParseDiagnostic) bool {
	for _, diagnostic := range diagnostics {
		if diagnostic.Severity == SeverityError {
			return true
		}
	}
	return false
}

type exactDecimal struct {
	Negative bool
	Digits   string
	Exponent *big.Int
}

func exactNumber(number json.Number) (exactDecimal, bool) {
	text := number.String()
	negative := strings.HasPrefix(text, "-")
	if negative {
		text = text[1:]
	}
	mantissa, exponentText := text, "0"
	if index := strings.IndexAny(text, "eE"); index >= 0 {
		mantissa, exponentText = text[:index], text[index+1:]
	}
	exponent, ok := new(big.Int).SetString(exponentText, 10)
	if !ok {
		return exactDecimal{}, false
	}
	whole, fraction := mantissa, ""
	if index := strings.IndexByte(mantissa, '.'); index >= 0 {
		whole, fraction = mantissa[:index], mantissa[index+1:]
	}
	digits := strings.TrimLeft(whole+fraction, "0")
	if digits == "" {
		return exactDecimal{Digits: "0", Exponent: new(big.Int)}, true
	}
	exponent.Sub(exponent, big.NewInt(int64(len(fraction))))
	trimmed := strings.TrimRight(digits, "0")
	exponent.Add(exponent, big.NewInt(int64(len(digits)-len(trimmed))))
	return exactDecimal{Negative: negative, Digits: trimmed, Exponent: exponent}, true
}

func isSafeInteger(number json.Number) bool {
	value, ok := exactNumber(number)
	if !ok || value.Digits == "0" {
		return ok
	}
	if value.Exponent.Sign() < 0 || !value.Exponent.IsInt64() {
		return false
	}
	zeros := value.Exponent.Int64()
	if zeros > 16 || int64(len(value.Digits))+zeros > 16 {
		return false
	}
	digits := value.Digits + strings.Repeat("0", int(zeros))
	return len(digits) < 16 || digits <= "9007199254740991"
}

func isFiniteNumber(number json.Number) bool {
	_, ok := exactNumber(number)
	return ok
}

func sameJSON(left, right any) bool {
	leftNumber, leftIsNumber := left.(json.Number)
	rightNumber, rightIsNumber := right.(json.Number)
	if leftIsNumber || rightIsNumber {
		if !leftIsNumber || !rightIsNumber {
			return false
		}
		leftValue, leftOK := exactNumber(leftNumber)
		rightValue, rightOK := exactNumber(rightNumber)
		return leftOK && rightOK && leftValue.Negative == rightValue.Negative &&
			leftValue.Digits == rightValue.Digits && leftValue.Exponent.Cmp(rightValue.Exponent) == 0
	}
	leftArray, leftIsArray := left.([]any)
	rightArray, rightIsArray := right.([]any)
	if leftIsArray || rightIsArray {
		if !leftIsArray || !rightIsArray || len(leftArray) != len(rightArray) {
			return false
		}
		for index := range leftArray {
			if !sameJSON(leftArray[index], rightArray[index]) {
				return false
			}
		}
		return true
	}
	leftObject, leftIsObject := left.(map[string]any)
	rightObject, rightIsObject := right.(map[string]any)
	if leftIsObject || rightIsObject {
		if !leftIsObject || !rightIsObject || len(leftObject) != len(rightObject) {
			return false
		}
		for key, leftValue := range leftObject {
			rightValue, ok := rightObject[key]
			if !ok || !sameJSON(leftValue, rightValue) {
				return false
			}
		}
		return true
	}
	return reflect.DeepEqual(left, right)
}

func joinPath(path, key string) string {
	escaped := strings.ReplaceAll(strings.ReplaceAll(key, "~", "~0"), "/", "~1")
	return path + "/" + escaped
}

func jsonText(value any) string {
	encoded, err := json.Marshal(value)
	if err != nil {
		return "<invalid JSON>"
	}
	return string(encoded)
}

func addError(diagnostics *[]ParseDiagnostic, path string, code DiagnosticCode, message string) {
	*diagnostics = append(*diagnostics, ParseDiagnostic{
		Path: path, Code: code, Severity: SeverityError, Message: message,
	})
}

